package com.library.catalogidentity;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.dao.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.sql.Clob;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static com.library.catalogattributes.CatalogAttributeSupport.*;
import static com.library.catalogidentity.CatalogIdentitySupport.normalized;

/** B35 stable IDs. A preview saves evidence; only explicit administrator confirmation changes links. */
@Service
public class CatalogIdentityService {
    private final JdbcTemplate jdbc;
    private final PlatformTransactionManager transactions;
    private static final int MAX_IDENTITIES=2000,MAX_ALIASES=10000;
    private static final List<String> DIMENSIONS=List.of("TOPIC","LEGACY_AGE","UNVERIFIED");
    public CatalogIdentityService(JdbcTemplate jdbc,PlatformTransactionManager transactions){this.jdbc=new CatalogIdentityJdbc(Objects.requireNonNull(jdbc.getDataSource()));this.transactions=transactions;}
    public static Actor actor(Authentication a){return com.library.catalogattributes.CatalogAttributeSupport.actor(a);}
    private <T>T tx(int isolation,boolean readOnly,Supplier<T> work){TransactionTemplate t=new TransactionTemplate(transactions);t.setIsolationLevel(isolation);t.setReadOnly(readOnly);t.setTimeout(15);try{return t.execute(s->work.get());}catch(Failure e){throw e;}catch(QueryTimeoutException|PessimisticLockingFailureException|TransactionTimedOutException e){throw conflict("CATALOG_IDENTITY_BUSY");}catch(DataAccessException e){throw fail(500,"CATALOG_IDENTITY_SAVE_FAILED");}}
    private static String string(Object v){if(v==null)return null;if(v instanceof JsonNode n)return n.isNull()?null:n.textValue();if(v instanceof Clob c)try{return c.getSubString(1,Math.toIntExact(c.length()));}catch(Exception e){throw fail(500,"CATALOG_IDENTITY_SAVE_FAILED");}return v.toString();}
    private Map<String,Object> bookRow(long id,boolean lock){if(id<=0)invalid();var rows=jdbc.queryForList("SELECT id,title,publisher,category_id,deleted,catalog_identity_revision FROM book WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty()||num(rows.get(0).get("deleted"))!=0)throw fail(404,"BOOK_NOT_FOUND");return rows.get(0);}

    /** Fixed four-query dictionary load, bounded for the local catalog. No contact fields are selected. */
    private final class Dictionary {
        final TreeMap<Long,ObjectNode> publishers=new TreeMap<>(),categories=new TreeMap<>();
        Dictionary(){
            var p=jdbc.queryForList("SELECT id,name,status,deleted,catalog_identity_revision FROM publisher ORDER BY id LIMIT ?",MAX_IDENTITIES+1);
            var c=jdbc.queryForList("SELECT c.id,c.name,c.parent_id,c.level,c.sort_order,c.status,c.deleted,c.catalog_identity_revision,COALESCE(p.dimension,'UNVERIFIED') AS dimension FROM book_category c LEFT JOIN catalog_category_profile p ON p.category_id=c.id ORDER BY c.id LIMIT ?",MAX_IDENTITIES+1);
            if(p.size()>MAX_IDENTITIES||c.size()>MAX_IDENTITIES)throw conflict("CATALOG_IDENTITY_LIMIT_EXCEEDED");
            for(var r:p)publishers.put(num(r.get("id")),obj("id",num(r.get("id")),"name",r.get("name"),"normalizedName",normalized(string(r.get("name"))),"status",r.get("status"),"deleted",r.get("deleted"),"revision",num(r.get("catalog_identity_revision")),"aliases",JSON.createArrayNode()));
            for(var r:c)categories.put(num(r.get("id")),obj("id",num(r.get("id")),"name",r.get("name"),"normalizedName",normalized(string(r.get("name"))),"status",r.get("status"),"deleted",r.get("deleted"),"parentId",num(r.get("parent_id")),"level",r.get("level"),"sortOrder",r.get("sort_order"),"dimension",r.get("dimension"),"revision",num(r.get("catalog_identity_revision")),"aliases",JSON.createArrayNode()));
            loadAliases("PUBLISHER",publishers);loadAliases("CATEGORY",categories);
            for(ObjectNode category:categories.values()) {
                List<String> path=new ArrayList<>();List<JsonNode> chain=new ArrayList<>();Set<Long> seen=new HashSet<>();long id=category.path("id").asLong();boolean active=true;
                while(id!=0){ObjectNode current=categories.get(id);if(current==null||!seen.add(id)||seen.size()>50||current.path("deleted").asInt()!=0){active=false;break;}path.add(current.path("name").asText());chain.add(obj("id",current.get("id"),"name",current.get("name"),"status",current.get("status"),"dimension",current.get("dimension"),"parentId",current.get("parentId"),"revision",current.get("revision")));if(current.path("status").asInt()!=1)active=false;id=current.path("parentId").asLong();}
                Collections.reverse(path);Collections.reverse(chain);category.put("path",String.join(" / ",path)).put("parentChainActive",active);category.set("parentChain",tree(chain));
            }
        }
        private void loadAliases(String kind,Map<Long,ObjectNode> owners){String table=kind.equals("PUBLISHER")?"catalog_publisher_alias":"catalog_category_alias",col=kind.equals("PUBLISHER")?"publisher_id":"category_id";var rows=jdbc.queryForList("SELECT id,"+col+",alias_name,normalized_name,origin,status,revision FROM "+table+" ORDER BY id LIMIT ?",MAX_ALIASES+1);if(rows.size()>MAX_ALIASES)throw conflict("CATALOG_IDENTITY_LIMIT_EXCEEDED");for(var r:rows){ObjectNode owner=owners.get(num(r.get(col)));if(owner!=null)((ArrayNode)owner.get("aliases")).add(obj("id",num(r.get("id")),"name",r.get("alias_name"),"normalizedName",r.get("normalized_name"),"origin",r.get("origin"),"status",r.get("status"),"revision",num(r.get("revision"))));}}
        ObjectNode owner(String kind,long id){ObjectNode o=(kind.equals("PUBLISHER")?publishers:categories).get(id);if(o==null||o.path("deleted").asInt()!=0)throw conflict(kind.equals("PUBLISHER")?"PUBLISHER_NOT_FOUND":"CATEGORY_NOT_FOUND");return o;}
        List<Long> chain(long id,boolean active){List<Long> ids=new ArrayList<>();Set<Long> seen=new HashSet<>();long cursor=id;while(cursor!=0){if(!seen.add(cursor)||ids.size()>=50)throw conflict("CATEGORY_PARENT_INVALID");ObjectNode node=owner("CATEGORY",cursor);if(active&&node.path("status").asInt()!=1)throw conflict("CATEGORY_PARENT_DISABLED");ids.add(cursor);cursor=node.path("parentId").asLong();}return ids;}
        void activeOwner(String kind,long id){ObjectNode o=owner(kind,id);if(o.path("status").asInt()!=1)throw conflict(kind.equals("PUBLISHER")?"PUBLISHER_DISABLED":"CATEGORY_PARENT_DISABLED");if(kind.equals("CATEGORY"))chain(id,true);}
    }

    private ObjectNode identity(long id,boolean lock,Dictionary d){Map<String,Object>b=bookRow(id,lock);ObjectNode p=null;var links=jdbc.queryForList("SELECT publisher_id,source_name,relation_kind,revision FROM catalog_book_publisher WHERE book_id=?",id);if(!links.isEmpty()){var r=links.get(0);p=d.owner("PUBLISHER",num(r.get("publisher_id"))).deepCopy();p.put("sourceName",string(r.get("source_name"))).put("relationKind",string(r.get("relation_kind"))).put("linkRevision",num(r.get("revision")));}ArrayNode themes=JSON.createArrayNode();for(var r:jdbc.queryForList("SELECT category_id,source_name,relation_kind,revision FROM catalog_book_theme WHERE book_id=? ORDER BY category_id",id)){long cid=num(r.get("category_id"));ObjectNode c=d.owner("CATEGORY",cid).deepCopy();c.put("categoryId",cid).put("sourceName",string(r.get("source_name"))).put("relationKind",string(r.get("relation_kind"))).put("linkRevision",num(r.get("revision")));themes.add(c);}ObjectNode v=obj("schemaVersion",1,"bookId",id,"publisherRaw",b.get("publisher"),"publisherId",p==null?null:p.get("id"),"categoryId",b.get("category_id"),"categoryFieldKind","LEGACY","identityRevision",num(b.get("catalog_identity_revision")),"publisher",p,"themes",themes);digestIdentity(v);return v;}
    private void digestIdentity(ObjectNode v){ObjectNode payload=v.deepCopy();payload.remove(List.of("catalogDigest","candidates"));v.put("catalogDigest",hash(payload));}
    public JsonNode book(long id,Actor a){a.role();return tx(TransactionDefinition.ISOLATION_REPEATABLE_READ,true,()->{Dictionary d=new Dictionary();ObjectNode v=identity(id,false,d);if(a.admin())v.set("candidates",candidates(v,d));return v;});}
    public JsonNode publishers(String keyword,int page,int size,Actor a){return list("PUBLISHER",keyword,page,size,a);}
    public JsonNode categories(String keyword,int page,int size,Actor a){return list("CATEGORY",keyword,page,size,a);}
    // Compatibility overloads for callers using the first draft.
    public JsonNode publishers(String keyword,Actor a){return publishers(keyword,1,50,a);}
    public JsonNode categories(String keyword,Actor a){return categories(keyword,1,50,a);}
    private JsonNode list(String kind,String keyword,int page,int size,Actor a){a.role();if(page<1||size<1||size>100||keyword!=null&&keyword.codePointCount(0,keyword.length())>200)invalid();return tx(TransactionDefinition.ISOLATION_REPEATABLE_READ,true,()->{Dictionary d=new Dictionary();String q=keyword==null?"":normalized(keyword);List<JsonNode> all=new ArrayList<>();for(ObjectNode o:(kind.equals("PUBLISHER")?d.publishers:d.categories).values())if(o.path("deleted").asInt()==0&&(q.isEmpty()||o.path("normalizedName").asText().contains(q)||hasAlias(o,q)))all.add(o);int from=(int)Math.min(all.size(),(long)(page-1)*size),to=Math.min(all.size(),from+size);return obj("records",all.subList(from,to),"total",all.size(),"page",page,"size",size,"pages",(all.size()+size-1)/size);});}
    private boolean hasAlias(JsonNode o,String q){for(JsonNode alias:o.path("aliases"))if(alias.path("status").asText().equals("ACTIVE")&&alias.path("normalizedName").asText().contains(q))return true;return false;}

    private ArrayNode candidates(JsonNode book,Dictionary d){ArrayNode out=JSON.createArrayNode();String raw=string(book.get("publisherRaw"));if(raw!=null&&!raw.isBlank()){for(ObjectNode o:d.publishers.values()){if(o.path("deleted").asInt()!=0)continue;candidate(out,"PUBLISHER",raw,o.path("name").textValue(),o,"legacy_book_publisher");for(JsonNode alias:o.path("aliases"))if(alias.path("status").asText().equals("ACTIVE"))candidate(out,"PUBLISHER",raw,alias.path("name").textValue(),o,"publisher_alias");}if(out.isEmpty())out.add(obj("id",null,"kind","PUBLISHER","entityId",null,"name",null,"rawName",raw,"normalizedValue",normalized(raw),"matchKind","UNMATCHED","status","PENDING","evidence",obj("basis","legacy_book_publisher")));}if(!book.path("categoryId").isNull()){ObjectNode c=d.categories.get(book.path("categoryId").asLong());if(c!=null&&c.path("deleted").asInt()==0)out.add(obj("id",null,"kind","CATEGORY","entityId",c.get("id"),"name",c.get("name"),"rawName",c.get("name"),"normalizedValue",c.get("normalizedName"),"matchKind","EXACT","status","PENDING","evidence",obj("basis","legacy_book_category_id","dimension",c.get("dimension"))));}if(out.size()>100)throw conflict("CATALOG_IDENTITY_CANDIDATE_LIMIT");return out;}
    private void candidate(ArrayNode out,String kind,String raw,String name,ObjectNode owner,String basis){String match=CatalogIdentitySupport.match(raw,name,normalized(raw),normalized(name));if(!match.equals("UNMATCHED"))out.add(obj("id",null,"kind",kind,"entityId",owner.get("id"),"name",owner.get("name"),"rawName",raw,"normalizedValue",normalized(raw),"matchKind",match,"status","PENDING","evidence",obj("basis",basis,"matchedName",name,"targetRevision",owner.get("revision"))));}

    private ObjectNode validate(JsonNode raw,Actor a){a.source();if(raw==null||!raw.isObject())invalid();ObjectNode n=raw.deepCopy();if(!n.has("sourceDigest"))n.putNull("sourceDigest");keys(n,"operationKey,mode,reason,bookId,expectedRevision,expectedCatalogDigest,sourceDigest,changes");key(n.get("operationKey"));String mode=word(n.get("mode"),List.of("MANUAL","SOURCE"));if(mode.equals("SOURCE"))throw conflict("CATALOG_IDENTITY_SOURCE_NOT_ENABLED");text(n.get("reason"),500);number(n.get("bookId"),true);number(n.get("expectedRevision"),false);digest(n.get("expectedCatalogDigest"));if(!n.get("sourceDigest").isNull())invalid();if(!n.path("changes").isObject())invalid();ObjectNode c=(ObjectNode)n.get("changes");for(String field:List.of("publisher","themes"))if(!c.has(field))c.putNull(field);for(String field:List.of("aliases","categoryDimensions"))if(!c.has(field))c.set(field,JSON.createArrayNode());keys(c,"publisher,themes,aliases,categoryDimensions");
        JsonNode p=c.get("publisher");if(!p.isNull()){keys(p,"action,publisherId");String action=word(p.get("action"),List.of("LINK","CLEAR"));if(action.equals("LINK"))number(p.get("publisherId"),true);else if(!p.get("publisherId").isNull())invalid();}
        JsonNode themes=c.get("themes");if(!themes.isNull()){keys(themes,"action,categoryIds");word(themes.get("action"),List.of("REPLACE"));ArrayNode ids=sortedIds(themes.get("categoryIds"));((ObjectNode)themes).set("categoryIds",ids);}
        JsonNode aliases=c.get("aliases");if(!aliases.isArray()||aliases.size()>50)invalid();Set<String> unique=new HashSet<>();for(JsonNode v:aliases){keys(v,"kind,ownerId,action,name");String kind=word(v.get("kind"),List.of("PUBLISHER","CATEGORY"));long id=number(v.get("ownerId"),true);word(v.get("action"),List.of("ADD","CLEAR"));String name=text(v.get("name"),kind.equals("PUBLISHER")?200:100);if(!unique.add(kind+":"+id+":"+Base64.getEncoder().encodeToString(bytes(name))))invalid();}
        JsonNode dimensions=c.get("categoryDimensions");if(!dimensions.isArray()||dimensions.size()>50)invalid();Set<Long> changedDims=new HashSet<>();for(JsonNode v:dimensions){keys(v,"categoryId,dimension");if(!changedDims.add(number(v.get("categoryId"),true)))invalid();word(v.get("dimension"),DIMENSIONS);}
        return (ObjectNode)canonical(n);
    }
    private ArrayNode sortedIds(JsonNode n){if(n==null||!n.isArray()||n.size()>50)invalid();TreeSet<Long> ids=new TreeSet<>();for(JsonNode id:n)if(!ids.add(number(id,true)))invalid();return (ArrayNode)tree(ids);}
    private String inputHash(JsonNode n,Actor a){return hash(obj("actorId",a.id(),"input",n));}
    private Map<String,Object> request(Long id,String key,boolean lock){var rows=jdbc.queryForList("SELECT * FROM catalog_identity_request WHERE "+(id==null?"operation_key=?":"id=?")+(lock?" FOR UPDATE":""),id==null?bytes(key):id);return rows.isEmpty()?null:rows.get(0);}
    private void owned(Map<String,Object> r,Actor a){a.source();if(r==null)throw fail(404,"REQUEST_NOT_FOUND");if(num(r.get("actor_id"))!=a.id())throw fail(403,"OWNER_REQUIRED");}
    private JsonNode requestView(Map<String,Object> r){return obj("requestId",num(r.get("id")),"operationKey",new String((byte[])r.get("operation_key"),java.nio.charset.StandardCharsets.UTF_8),"mode",r.get("mode"),"state",r.get("state"),"previewDigest",r.get("preview_digest"),"expiresAt",time(r.get("expires_at")),"preview",read(string(r.get("preview_json"))),"receipt",r.get("receipt_json")==null?null:read(string(r.get("receipt_json"))));}
    public JsonNode getRequest(long id,Actor a){a.source();if(id<=0)invalid();return tx(TransactionDefinition.ISOLATION_REPEATABLE_READ,true,()->{var r=request(id,null,false);owned(r,a);return requestView(r);});}
    public JsonNode getByKey(String k,Actor a){a.source();key(tree(k));return tx(TransactionDefinition.ISOLATION_REPEATABLE_READ,true,()->{var r=request(null,k,false);owned(r,a);return requestView(r);});}
    private JsonNode duplicate(Map<String,Object> r,JsonNode n,Actor a){if(num(r.get("actor_id"))!=a.id()||!r.get("input_hash").equals(inputHash(n,a)))throw conflict("IDEMPOTENCY_KEY_REUSED");return requestView(r);}
    private void expected(JsonNode input,JsonNode current){if(input.path("expectedRevision").asLong()!=current.path("identityRevision").asLong()||!input.path("expectedCatalogDigest").asText().equals(current.path("catalogDigest").asText()))throw conflict("CATALOG_IDENTITY_CHANGED");}

    private record Change(ObjectNode after,ObjectNode targets,ObjectNode afterTargets,ArrayNode fields,ArrayNode aliases,boolean changed){}
    private Change change(ObjectNode before,JsonNode input,Dictionary d){JsonNode changes=input.path("changes");TreeSet<Long> ps=new TreeSet<>(),cs=new TreeSet<>();if(!before.path("publisherId").isNull())ps.add(before.path("publisherId").asLong());for(JsonNode theme:before.path("themes"))cs.addAll(d.chain(theme.path("categoryId").asLong(),false));JsonNode publisher=changes.get("publisher");if(!publisher.isNull()&&publisher.path("action").asText().equals("LINK")){long id=publisher.path("publisherId").asLong();d.activeOwner("PUBLISHER",id);ps.add(id);}JsonNode themes=changes.get("themes");if(!themes.isNull())for(JsonNode id:themes.path("categoryIds"))cs.addAll(d.chain(id.asLong(),true));for(JsonNode alias:changes.path("aliases")){String kind=alias.path("kind").asText();long id=alias.path("ownerId").asLong();d.activeOwner(kind,id);if(kind.equals("PUBLISHER"))ps.add(id);else cs.addAll(d.chain(id,true));}for(JsonNode dim:changes.path("categoryDimensions"))cs.addAll(d.chain(dim.path("categoryId").asLong(),true));ObjectNode targets=targetSnapshot(ps,cs,d),afterTargets=targets.deepCopy();Set<Long> referenced=changes.path("categoryDimensions").isEmpty()?Set.of():referencedCategories(d);ArrayNode fields=JSON.createArrayNode(),aliasChanges=JSON.createArrayNode();
        for(JsonNode dim:changes.path("categoryDimensions")){long id=dim.path("categoryId").asLong();ObjectNode target=findTarget(afterTargets,"CATEGORY",id);String value=dim.path("dimension").asText();if(!target.path("dimension").asText().equals(value)){if(!value.equals("TOPIC")&&referenced.contains(id))throw conflict("CATEGORY_DIMENSION_REFERENCED");target.put("dimension",value);bump(target,targets,"CATEGORY",id);add(fields,"categoryDimensions");}}
        for(JsonNode alias:changes.path("aliases")){String kind=alias.path("kind").asText(),name=alias.path("name").textValue(),action=alias.path("action").asText();long owner=alias.path("ownerId").asLong();ObjectNode target=findTarget(afterTargets,kind,owner);ArrayNode old=target.withArray("aliases").deepCopy(),next=old.deepCopy();ObjectNode found=null;for(JsonNode v:next)if(name.equals(v.path("name").textValue())){found=(ObjectNode)v;break;}boolean changed=false;if(action.equals("ADD")){if(found==null){next.add(obj("id",null,"name",name,"normalizedName",normalized(name),"origin","MANUAL","status","ACTIVE","revision",1));changed=true;}else if(!found.path("status").asText().equals("ACTIVE")){found.put("status","ACTIVE").put("revision",found.path("revision").asLong()+1);changed=true;}}else if(found!=null&&found.path("status").asText().equals("ACTIVE")){found.put("status","RETIRED").put("revision",found.path("revision").asLong()+1);changed=true;}if(changed){target.set("aliases",next);bump(target,targets,kind,owner);add(fields,"aliases");}aliasChanges.add(obj("kind",kind,"ownerId",owner,"ownerName",target.get("name"),"action",action,"name",name,"beforeAliases",old,"afterAliases",next,"willChange",changed));}
        refreshDerived(afterTargets);
        ObjectNode after=before.deepCopy();after.remove("candidates");boolean linkChanged=false;
        if(!publisher.isNull()){if(publisher.path("action").asText().equals("CLEAR")){if(!before.path("publisherId").isNull()){after.putNull("publisherId");after.putNull("publisher");linkChanged=true;}}else{long id=publisher.path("publisherId").asLong();if(before.path("publisherId").isNull()||before.path("publisherId").asLong()!=id){after.put("publisherId",id);after.set("publisher",findTarget(afterTargets,"PUBLISHER",id).deepCopy());linkChanged=true;}}if(linkChanged)add(fields,"publisher");}
        if(!themes.isNull()){ArrayNode wanted=(ArrayNode)themes.path("categoryIds");ArrayNode existing=JSON.createArrayNode();for(JsonNode v:before.path("themes"))existing.add(v.path("categoryId").asLong());for(JsonNode id:wanted){for(Long cid:d.chain(id.asLong(),true))if(!findTarget(afterTargets,"CATEGORY",cid).path("dimension").asText().equals("TOPIC"))throw conflict("CATEGORY_TOPIC_REQUIRED");}if(!hash(existing).equals(hash(wanted))){ArrayNode next=JSON.createArrayNode();for(JsonNode id:wanted){ObjectNode t=findTarget(afterTargets,"CATEGORY",id.asLong()).deepCopy();t.put("categoryId",id.asLong()).put("sourceName",t.path("name").textValue()).put("relationKind","CONFIRMED");next.add(t);}after.set("themes",next);add(fields,"themes");}}
        boolean changed=!fields.isEmpty();long revision=before.path("identityRevision").asLong();if(changed){if(revision==Long.MAX_VALUE)throw conflict("CATALOG_IDENTITY_CHANGED");revision++;after.put("identityRevision",revision);}if(!after.path("publisherId").isNull()){long id=after.path("publisherId").asLong();ObjectNode prior=(ObjectNode)after.get("publisher"),target=findTarget(afterTargets,"PUBLISHER",id).deepCopy();target.put("sourceName",contains(fields,"publisher")?string(before.get("publisherRaw")):string(prior.get("sourceName"))).put("relationKind","CONFIRMED").put("linkRevision",contains(fields,"publisher")?revision:prior.path("linkRevision").asLong());after.set("publisher",target);}ArrayNode updatedThemes=JSON.createArrayNode();for(JsonNode t:after.path("themes")){long id=t.path("categoryId").asLong();ObjectNode target=findTarget(afterTargets,"CATEGORY",id).deepCopy();target.put("categoryId",id).put("sourceName",t.path("sourceName").textValue()).put("relationKind","CONFIRMED").put("linkRevision",contains(fields,"themes")?revision:t.path("linkRevision").asLong());updatedThemes.add(target);}after.set("themes",updatedThemes);digestIdentity(after);return new Change(after,targets,afterTargets,fields,aliasChanges,changed);
    }
    private boolean contains(ArrayNode a,String value){for(JsonNode n:a)if(n.asText().equals(value))return true;return false;}
    private void add(ArrayNode a,String value){if(!contains(a,value))a.add(value);}
    private void bump(ObjectNode target,JsonNode beforeTargets,String kind,long id){long revision=findTarget(beforeTargets,kind,id).path("revision").asLong();if(revision==Long.MAX_VALUE)throw conflict("CATALOG_IDENTITY_CHANGED");target.put("revision",revision+1);}
    private Set<Long> referencedCategories(Dictionary d){Set<Long> result=new HashSet<>();for(Long id:jdbc.queryForList("SELECT DISTINCT category_id FROM catalog_book_theme",Long.class))result.addAll(d.chain(id,false));return result;}
    private ObjectNode targetSnapshot(Set<Long> ps,Set<Long> cs,Dictionary d){ArrayNode p=JSON.createArrayNode(),c=JSON.createArrayNode();ps.forEach(id->p.add(d.owner("PUBLISHER",id).deepCopy()));cs.forEach(id->c.add(d.owner("CATEGORY",id).deepCopy()));return obj("publishers",p,"categories",c);}
    private ObjectNode findTarget(JsonNode snapshot,String kind,long id){for(JsonNode n:snapshot.path(kind.equals("PUBLISHER")?"publishers":"categories"))if(n.path("id").asLong()==id)return(ObjectNode)n;throw conflict("CATALOG_IDENTITY_CHANGED");}
    private void refreshDerived(ObjectNode snapshot){for(JsonNode row:snapshot.path("categories")){ObjectNode c=(ObjectNode)row;List<JsonNode> chain=new ArrayList<>();List<String> names=new ArrayList<>();Set<Long> seen=new HashSet<>();long id=c.path("id").asLong();while(id!=0){if(!seen.add(id))throw conflict("CATEGORY_PARENT_INVALID");ObjectNode parent=findTarget(snapshot,"CATEGORY",id);chain.add(obj("id",parent.get("id"),"name",parent.get("name"),"status",parent.get("status"),"dimension",parent.get("dimension"),"parentId",parent.get("parentId"),"revision",parent.get("revision")));names.add(parent.path("name").asText());id=parent.path("parentId").asLong();}Collections.reverse(chain);Collections.reverse(names);c.set("parentChain",tree(chain));c.put("path",String.join(" / ",names));}}

    private ObjectNode preview(JsonNode input,ObjectNode before,Dictionary d){Change c=change(before,input,d);String at=now();return obj("schemaVersion",1,"mode","MANUAL","reason",input.get("reason"),"createdAt",at,"expiresAt",Instant.parse(at).plusSeconds(900).toString(),"book",obj("bookId",input.get("bookId"),"expectedRevision",before.get("identityRevision"),"catalogDigest",before.get("catalogDigest"),"before",before,"after",c.after,"changedFields",c.fields,"willChange",c.changed,"changes",input.get("changes"),"targetSnapshot",c.targets,"afterTargetSnapshot",c.afterTargets,"aliasChanges",c.aliases,"candidates",candidates(before,d),"sourceDigest",null,"sourceStatus","MANUAL_LEGACY_EVIDENCE"));}
    private static final class DuplicatePreview extends RuntimeException{}
    public JsonNode preview(JsonNode input,Actor a){ObjectNode n=validate(input,a);try{return tx(TransactionDefinition.ISOLATION_REPEATABLE_READ,false,()->{var existing=request(null,n.path("operationKey").asText(),false);if(existing!=null)return duplicate(existing,n,a);Dictionary d=new Dictionary();ObjectNode before=identity(n.path("bookId").asLong(),false,d);expected(n,before);ObjectNode p=preview(n,before,d);long id;try{id=insert(jdbc,"INSERT INTO catalog_identity_request(operation_key,book_id,actor_id,mode,input_hash,schema_version,request_json,preview_json,preview_digest,state,created_at,expires_at) VALUES (?,?,?,'MANUAL',?,1,?,?,?,'PREVIEWED',?,?)",bytes(n.path("operationKey").asText()),n.path("bookId").asLong(),a.id(),inputHash(n,a),write(n),write(p),hash(p),local(p.path("createdAt").asText()),local(p.path("expiresAt").asText()));}catch(DuplicateKeyException e){throw new DuplicatePreview();}for(JsonNode c:p.path("book").path("candidates"))insert(jdbc,"INSERT INTO catalog_identity_candidate(request_id,book_id,entity_kind,raw_value,normalized_value,match_kind,candidate_id,evidence_json,status,created_at) VALUES (?,?,?,?,?,?,?,?,'PENDING',?)",id,n.path("bookId").asLong(),c.path("kind").asText(),string(c.get("rawName")),string(c.get("normalizedValue")),c.path("matchKind").asText(),c.path("entityId").isNull()?null:c.path("entityId").asLong(),write(c.get("evidence")),local(p.path("createdAt").asText()));saveTargetReferences(id,n.path("bookId").asLong(),p);return requestView(request(id,null,false));});}catch(DuplicatePreview race){return tx(TransactionDefinition.ISOLATION_REPEATABLE_READ,true,()->{var r=request(null,n.path("operationKey").asText(),false);if(r==null)throw conflict("CATALOG_IDENTITY_BUSY");return duplicate(r,n,a);});}}

    public JsonNode confirm(long id,JsonNode input,Actor a){a.source();if(id<=0)invalid();keys(input,"operationKey,previewDigest");key(input.get("operationKey"));digest(input.get("previewDigest"));return tx(TransactionDefinition.ISOLATION_READ_COMMITTED,false,()->{CatalogIdentityHistory.lock(jdbc);var r=request(id,null,true);owned(r,a);if(!Arrays.equals((byte[])r.get("operation_key"),bytes(input.path("operationKey").asText()))||!r.get("preview_digest").equals(input.path("previewDigest").asText()))throw conflict("CATALOG_IDENTITY_CHANGED");if(r.get("state").equals("COMMITTED"))return read(string(r.get("receipt_json")));if(!Instant.parse(time(r.get("expires_at"))).isAfter(Instant.now()))throw conflict("PREVIEW_EXPIRED");JsonNode n=read(string(r.get("request_json"))),p=read(string(r.get("preview_json")));long book=n.path("bookId").asLong();bookRow(book,true);lockTargets(p.path("book").get("targetSnapshot"));Dictionary d=new Dictionary();ObjectNode before=identity(book,false,d);expected(n,before);Change c=change(before,n,d);JsonNode prior=p.path("book");if(!hash(c.targets).equals(hash(prior.get("targetSnapshot")))||!hash(c.afterTargets).equals(hash(prior.get("afterTargetSnapshot")))||!hash(c.after).equals(hash(prior.get("after")))||!c.fields.equals(prior.get("changedFields"))||!hash(c.aliases).equals(hash(prior.get("aliasChanges"))))throw conflict("CATALOG_IDENTITY_CHANGED");
        if(c.changed){applyTargets(id,book,n,c,a);applyLinks(book,n,c);if(jdbc.update("UPDATE book SET catalog_identity_revision=?,update_time=update_time WHERE id=? AND catalog_identity_revision=?",c.after.path("identityRevision").asLong(),book,before.path("identityRevision").asLong())!=1)throw conflict("CATALOG_IDENTITY_CHANGED");}
        Dictionary saved=new Dictionary();ObjectNode after=identity(book,false,saved);if(!hash(withoutGeneratedIds(after)).equals(hash(withoutGeneratedIds(c.after))))throw fail(500,"CATALOG_IDENTITY_SAVE_FAILED");Long event=null;if(c.changed)event=CatalogIdentityHistory.event(jdbc,id,book,"BOOK_PUBLISHER",null,before.path("identityRevision").asLong(),after.path("identityRevision").asLong(),c.fields,before,after,obj("targetSnapshot",c.targets,"afterTargetSnapshot",c.afterTargets,"aliasChanges",c.aliases),a.id(),n.path("reason").asText());updateCandidates(id,n);JsonNode receipt=obj("schemaVersion",1,"requestId",id,"operationKey",n.get("operationKey"),"mode","MANUAL","actorId",a.id(),"confirmedAt",now(),"book",obj("bookId",book,"changed",c.changed,"beforeRevision",before.get("identityRevision"),"afterRevision",after.get("identityRevision"),"eventId",event,"identity",after,"applied",n.get("changes"),"aliasChanges",c.aliases));if(jdbc.update("UPDATE catalog_identity_request SET state='COMMITTED',receipt_json=?,committed_at=? WHERE id=? AND state='PREVIEWED'",write(receipt),local(receipt.path("confirmedAt").asText()),id)!=1)throw conflict("CATALOG_IDENTITY_CHANGED");return read(write(receipt));});}
    private void lockTargets(JsonNode targets){for(String kind:List.of("PUBLISHER","CATEGORY")){String field=kind.equals("PUBLISHER")?"publishers":"categories";for(JsonNode row:targets.path(field))CatalogIdentityHistory.owner(jdbc,kind,row.path("id").asLong(),true);}}
    private void saveTargetReferences(long request,long book,JsonNode preview){for(String kind:List.of("PUBLISHER","CATEGORY"))for(JsonNode target:preview.path("book").path("targetSnapshot").path(kind.equals("PUBLISHER")?"publishers":"categories"))insert(jdbc,"INSERT INTO catalog_identity_candidate(request_id,book_id,entity_kind,raw_value,normalized_value,match_kind,candidate_id,evidence_json,status,created_at) VALUES (?,?,?,?,?,'UNMATCHED',?,?,'PENDING',?)",request,book,kind,target.path("name").textValue(),target.path("normalizedName").textValue(),target.path("id").asLong(),write(obj("basis","SELECTED_TARGET","targetRevision",target.get("revision"))),local(now()));}
    private JsonNode withoutGeneratedIds(JsonNode n){JsonNode value=n.deepCopy();stripAliasIds(value);if(value.isObject())((ObjectNode)value).remove("catalogDigest");return value;}
    private void stripAliasIds(JsonNode n){if(n.isObject()){for(Iterator<Map.Entry<String,JsonNode>> it=n.fields();it.hasNext();){var e=it.next();if(e.getKey().equals("aliases")&&e.getValue().isArray())for(JsonNode alias:e.getValue())((ObjectNode)alias).remove("id");else stripAliasIds(e.getValue());}}else if(n.isArray())n.forEach(this::stripAliasIds);}
    private void applyTargets(long request,long book,JsonNode n,Change change,Actor a){for(String kind:List.of("PUBLISHER","CATEGORY")){String field=kind.equals("PUBLISHER")?"publishers":"categories",table=kind.equals("PUBLISHER")?"publisher":"book_category",profile=kind.equals("PUBLISHER")?"catalog_publisher_profile":"catalog_category_profile",column=kind.equals("PUBLISHER")?"publisher_id":"category_id";for(JsonNode after:change.afterTargets.path(field)){long id=after.path("id").asLong();JsonNode before=findTarget(change.targets,kind,id);if(before.path("revision").asLong()==after.path("revision").asLong())continue;if(jdbc.update("UPDATE "+table+" SET catalog_identity_revision=?,update_time=update_time WHERE id=? AND catalog_identity_revision=?",after.path("revision").asLong(),id,before.path("revision").asLong())!=1)throw conflict("CATALOG_IDENTITY_CHANGED");String name=after.path("normalizedName").textValue();if(kind.equals("PUBLISHER")){jdbc.update("INSERT INTO "+profile+"("+column+",normalized_name,normalized_key,revision,updated_at) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE normalized_name=VALUES(normalized_name),normalized_key=VALUES(normalized_key),revision=VALUES(revision),updated_at=VALUES(updated_at)",id,name,bytes(name),after.path("revision").asLong(),local(now()));}else{jdbc.update("INSERT INTO "+profile+"("+column+",normalized_name,normalized_key,dimension,revision,updated_at) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE normalized_name=VALUES(normalized_name),normalized_key=VALUES(normalized_key),dimension=VALUES(dimension),revision=VALUES(revision),updated_at=VALUES(updated_at)",id,name,bytes(name),after.path("dimension").asText(),after.path("revision").asLong(),local(now()));}saveAliases(kind,id,before.path("aliases"),after.path("aliases"));CatalogIdentityHistory.event(jdbc,request,book,kind,id,before.path("revision").asLong(),after.path("revision").asLong(),List.of("identityMetadata"),before,after,null,a.id(),n.path("reason").asText());}}}
    private void saveAliases(String kind,long owner,JsonNode before,JsonNode after){String table=kind.equals("PUBLISHER")?"catalog_publisher_alias":"catalog_category_alias",column=kind.equals("PUBLISHER")?"publisher_id":"category_id";for(JsonNode alias:after){JsonNode old=null;for(JsonNode v:before)if(v.path("name").asText().equals(alias.path("name").asText())){old=v;break;}if(old!=null&&hash(old).equals(hash(alias)))continue;String name=alias.path("name").textValue();if(old==null)jdbc.update("INSERT INTO "+table+"("+column+",alias_name,alias_key,normalized_name,origin,status,revision,created_at,updated_at) VALUES (?,?,?,?,'MANUAL',?,1,?,?)",owner,name,bytes(name),normalized(name),alias.path("status").asText(),local(now()),local(now()));else jdbc.update("UPDATE "+table+" SET status=?,revision=?,updated_at=? WHERE id=? AND "+column+"=?",alias.path("status").asText(),alias.path("revision").asLong(),local(now()),old.path("id").asLong(),owner);}}
    private void applyLinks(long book,JsonNode n,Change c){if(contains(c.fields,"publisher")){jdbc.update("DELETE FROM catalog_book_publisher WHERE book_id=?",book);if(!c.after.path("publisherId").isNull())jdbc.update("INSERT INTO catalog_book_publisher(book_id,publisher_id,source_name,relation_kind,revision,updated_at) VALUES (?,?,?,'CONFIRMED',?,?)",book,c.after.path("publisherId").asLong(),string(c.after.get("publisherRaw")),c.after.path("identityRevision").asLong(),local(now()));}if(contains(c.fields,"themes")){jdbc.update("DELETE FROM catalog_book_theme WHERE book_id=?",book);for(JsonNode t:c.after.path("themes"))jdbc.update("INSERT INTO catalog_book_theme(book_id,category_id,source_name,relation_kind,revision,updated_at) VALUES (?,?,?,'CONFIRMED',?,?)",book,t.path("categoryId").asLong(),t.path("name").textValue(),c.after.path("identityRevision").asLong(),local(now()));}}
    private void updateCandidates(long id,JsonNode n){JsonNode c=n.path("changes"),p=c.path("publisher");if(!p.isNull()&&p.path("action").asText().equals("LINK"))jdbc.update("UPDATE catalog_identity_candidate SET status='CONFIRMED' WHERE request_id=? AND entity_kind='PUBLISHER' AND candidate_id=?",id,p.path("publisherId").asLong());JsonNode t=c.path("themes");if(!t.isNull())for(JsonNode category:t.path("categoryIds"))jdbc.update("UPDATE catalog_identity_candidate SET status='CONFIRMED' WHERE request_id=? AND entity_kind='CATEGORY' AND candidate_id=?",id,category.asLong());}
}
